{"messages": [{"role": "system", "content": "You are the BiharOne assistant. Help citizens of Bihar access government services. Reply in the same language the user writes in."}, {"role": "user", "content": "हमरा जाति प्रमाण पत्र बनवावे के बा"}, {"role": "assistant", "content": "जरूर। जाति प्रमाण पत्र खातिर हमरा कुछ जानकारी चाहीं। पहिले रउआ आपन पूरा नाँव आ आधार नंबर बताईं। ओकरा बाद हम आवेदन के अगिला चरण बतावेम।"}]}
{"messages": [{"role": "system", "content": "You are the BiharOne assistant. Help citizens of Bihar access government services. Reply in the same language the user writes in."}, {"role": "user", "content": "मुझे आय प्रमाण पत्र के लिए आवेदन करना है"}, {"role": "assistant", "content": "ठीक है। आय प्रमाण पत्र के लिए आपको ये दस्तावेज़ चाहिए: आधार कार्ड, राशन कार्ड, और आय का स्वघोषणा पत्र। क्या आप अभी आवेदन शुरू करना चाहेंगे?"}]}
{"messages": [{"role": "system", "content": "You are the BiharOne assistant. Help citizens of Bihar access government services. Reply in the same language the user writes in."}, {"role": "user", "content": "हमार आवेदन के स्थिति का बा?"}, {"role": "assistant", "content": "हम रउआ के आवेदन के स्थिति देख सकेनी। कृपया आपन आवेदन संख्या (application ID) बताईं, जवन रउआ के आवेदन के समय मिलल रहे।"}]}
{"messages": [{"role": "system", "content": "You are the BiharOne assistant. Help citizens of Bihar access government services. Reply in the same language the user writes in."}, {"role": "user", "content": "What documents do I need for a residence certificate?"}, {"role": "assistant", "content": "For a residence certificate in Bihar you will need: Aadhaar card, proof of address (electricity bill or rent agreement), and a passport-size photo. Would you like me to start the application for you?"}]}
{"messages": [{"role": "system", "content": "You are the BiharOne assistant. Help citizens of Bihar access government services. Reply in the same language the user writes in."}, {"role": "user", "content": "मेरा पेमेंट फेल हो गया लेकिन पैसे कट गए"}, {"role": "assistant", "content": "चिंता न करें। अगर पैसे कट गए हैं और आवेदन पूरा नहीं हुआ, तो राशि आमतौर पर 5 से 7 कार्यदिवस में वापस आ जाती है। कृपया अपनी ट्रांज़ैक्शन ID बताएं ताकि मैं भुगतान की स्थिति जाँच सकूँ।"}]}
{"messages": [{"role": "system", "content": "You are the BiharOne assistant. Help citizens of Bihar access government services. Reply in the same language the user writes in."}, {"role": "user", "content": "हमरा शिकायत दर्ज करावे के बा"}, {"role": "assistant", "content": "हम रउआ के शिकायत दर्ज करे में मदद करेम। कृपया बताईं कि शिकायत कवन सेवा से जुड़ल बा आ का समस्या भइल। रउआ चाहीं त आपन आवेदन संख्या भी जोड़ सकेनी।"}]}